DROP TABLE IF EXISTS `fuel_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fuel_logs` (
  `fuel_log_id` int NOT NULL AUTO_INCREMENT,
  `asset_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `refuel_date` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `flowmeter_start` decimal(10,2) NOT NULL,
  `flowmeter_end` decimal(10,2) NOT NULL,
  `liters_issued` decimal(10,2) NOT NULL,
  `current_hm_km` decimal(10,2) NOT NULL,
  `calculated_lph` decimal(6,2) DEFAULT NULL,
  `baseline_lph` decimal(6,2) DEFAULT NULL,
  `is_anomaly` tinyint(1) DEFAULT '0',
  `driver_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`fuel_log_id`),
  KEY `asset_id` (`asset_id`),
  CONSTRAINT `fuel_logs_ibfk_1` FOREIGN KEY (`asset_id`) REFERENCES `assets` (`asset_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=273 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
