--
-- Table structure for table `grease_logs`
--

DROP TABLE IF EXISTS `grease_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `grease_logs` (
  `grease_log_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `asset_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `current_hm` decimal(10,2) NOT NULL,
  `last_grease_hm` decimal(10,2) NOT NULL,
  `interval_hm` decimal(10,2) NOT NULL,
  `quantity_kg` decimal(10,2) NOT NULL DEFAULT '0.00',
  `grease_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `lubrication_points` json NOT NULL,
  `notes` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status_level` enum('success','warning','danger') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `inspected_by` int NOT NULL,
  `inspected_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`grease_log_id`),
  KEY `idx_grease_asset_date` (`asset_id`,`inspected_at`),
  KEY `fk_grease_inspector` (`inspected_by`),
  CONSTRAINT `fk_grease_asset` FOREIGN KEY (`asset_id`) REFERENCES `assets` (`asset_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_grease_inspector` FOREIGN KEY (`inspected_by`) REFERENCES `users` (`user_id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

