i',2026,'2026-01',NULL,NULL,2,8,'Biaya & Kualitas','Repeat Breakdown ??? 30 Hari','??? 5%',1,10.00,'Kerusakan berulang unit/komponen yang sama','DRAFT',1,NULL,NULL,NULL,NULL,'2026-10-23 12:29:01','2026-10-23 12:29:01'),(9,'Januari',2026,'2026-01',NULL,NULL,2,9,'Kepemimpinan','Monitoring & Pelaporan Unit','Konsisten',1,5.00,'Disiplin update JO mekanik, target RTW, & report harian','DRAFT',1,NULL,NULL,NULL,NULL,'2026-10-23 12:29:01','2026-10-23 12:29:01'),(10,'Januari',2026,'2026-01',NULL,NULL,2,10,'Kepemimpinan','Inisiatif Percepatan Perbaikan','Aktif',1,5.00,'Solusi percepatan (shift tambahan, vendor, prioritas)','DRAFT',1,NULL,NULL,NULL,NULL,'2026-10-23 12:29:01','2026-10-23 12:29:01');
