CREATE TABLE `parts_weekly_snapshots` (
  `snapshot_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `report_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `report_item_position` int unsigned NOT NULL,
  `part_id` int NOT NULL,
  `report_date` date NOT NULL,
  `yard` varchar(190) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `week_number` int NOT NULL,
  `report_year` int NOT NULL,
  `incoming_total` int NOT NULL,
