  `reported_balance` int NOT NULL,
  `actual_balance` int NOT NULL,
  `balance_variance` int NOT NULL,
  `unit_price` decimal(15,2) NOT NULL,
  `reported_value` decimal(15,2) NOT NULL,
  `notes` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `reversed_at` timestamp NULL DEFAULT NULL,
  `reversed_by` int DEFAULT NULL,
  PRIMARY KEY (`snapshot_id`),
  UNIQUE KEY `uq_parts_weekly_line` (`report_id`,`report_item_position`),
  KEY `idx_parts_weekly_part` (`part_id`,`report_date`,`reversed_at`),
